import { runRefresh } from '../src/lib/lab-refresh'
import { reason } from '../src/lib/refresh-reason'
// A separately bundled adapter keeps the command independent of a running Next server.
// @ts-expect-error Generated by bundle-refresh.mjs, not a source module.
import { persist } from './refresh-persist.mjs'

try {
	await runRefresh(process.env, { persist })
} catch (error) {
	console.error(`refresh failed: ${reason(error)}`)
	process.exitCode = 1
}
